REQUIRE LongShort == 1 OR LongShort == -1;    
REQUIRE Strike >= 0; REQUIRE Quantity >= 0;
REQUIRE SIZE(SettlementDates) == SIZE(ExerciseDates);

NUMBER _AMC_NPV[SIZE(_AMC_SimDates)];
NUMBER Option[SIZE(ExerciseAndSimDates) + 1], Payoff;
NUMBER exIdx, lastExIdx, ExerciseIndicator[SIZE(ExerciseDates)];
NUMBER i, j;

lastExIdx = DATEINDEX(ExerciseDates[SIZE(ExerciseDates)], ExerciseAndSimDates, EQ);
Option[lastExIdx] = PAY(
    max(PutCall * (Underlying(ExerciseDates[SIZE(ExerciseDates)]) - Strike), 0 ), 
    ExerciseDates[SIZE(ExerciseDates)], 
    SettlementDates[SIZE(ExerciseDates)], 
    PayCcy
);
FOR i IN (lastExIdx-1, 1, -1) DO
  Option[i] = Option[i + 1];
  exIdx = DATEINDEX(ExerciseAndSimDates[i], ExerciseDates, EQ);
  IF exIdx > 0 THEN
    Payoff = PAY(
        max(PutCall * (Underlying(ExerciseAndSimDates[i]) - Strike), 0 ), 
        ExerciseDates[exIdx], 
        SettlementDates[exIdx], 
        PayCcy
    );
    IF Payoff > 0 AND Payoff > NPVMEM( Option[i], ExerciseAndSimDates[i], i , Payoff > 0 ) THEN
      ExerciseIndicator[exIdx] = 1;
      Option[i] = Payoff;
      FOR j IN (exIdx + 1, SIZE(ExerciseDates), 1) DO
        ExerciseIndicator[j] = 0;
      END;
    END;
  END;
END;
FOR i IN (1, SIZE(_AMC_SimDates), 1) DO
  _AMC_NPV[i] = NPVMEM( Option[DATEINDEX(_AMC_SimDates[i], ExerciseAndSimDates, EQ)]* LongShort * Quantity, _AMC_SimDates[i], SIZE(ExerciseAndSimDates) + i);
END;
OptionValue = Option[1] * LongShort * Quantity;
